<template><VContainer><div class="d-flex justify-space-between align-center mb-6"><h1>Administradores</h1><VBtn v-if="canInvite" color="primary" @click="dialog=true">Invitar administrador</VBtn></div><VAlert v-if="message" type="success" class="mb-4">{{message}}</VAlert><VDataTable :headers="headers" :items="items"><template #item.actions="{item}"><template v-if="item.invitation"><VBtn size="small" variant="text" @click="resend(item.id)">Reenviar</VBtn><VBtn size="small" variant="text" color="error" @click="revoke(item.id)">Revocar</VBtn></template><VBtn v-else size="small" variant="text" @click="toggle(item)">{{item.status==='Activa'?'Desactivar':'Reactivar'}}</VBtn></template></VDataTable><VDialog v-model="dialog" max-width="560"><VCard class="pa-6"><h2>Invitar administrador</h2><VTextField v-model="form.first_name" label="Nombre"/><VTextField v-model="form.last_name" label="Apellido"/><VTextField v-model="form.email" label="Correo electrónico" type="email"/><VSelect v-model="form.role" label="Rol" :items="roles"/><VAlert v-if="error" type="error">{{error}}</VAlert><VCardActions><VBtn @click="dialog=false">Cancelar</VBtn><VBtn color="primary" @click="invite">Enviar invitación</VBtn></VCardActions></VCard></VDialog></VContainer></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{apiClient}from'@/services/apiClient';import{useTwoFactorGuard}from'@/composables/useTwoFactorGuard';const{runWithTwoFactor}=useTwoFactorGuard();const scope='admin.security' as const;const items=ref<any[]>([]),roles=ref<string[]>([]),canInvite=ref(false),dialog=ref(false),message=ref(''),error=ref('');const form=reactive({first_name:'',last_name:'',email:'',role:''});const headers=[{title:'Nombre',key:'name'},{title:'Correo',key:'email'},{title:'Rol',key:'role'},{title:'Estado',key:'status'},{title:'Último acceso',key:'last_access'},{title:'Acciones',key:'actions',sortable:false}];async function load(){const r=await apiClient.get<any>('/admin/administrators');items.value=r.data.administrators;roles.value=r.data.roles;canInvite.value=r.data.can_invite}async function invite(){await runWithTwoFactor(async()=>{try{await apiClient.post('/admin/administrators/invitations',form,{financialScope:scope});dialog.value=false;message.value='Invitación enviada correctamente.';await load()}catch(e:any){error.value=e.message||'Revisa los datos.'}},scope)}async function resend(id:number){await runWithTwoFactor(async()=>{await apiClient.post(`/admin/administrators/invitations/${id}/resend`,undefined,{financialScope:scope});message.value='Invitación reenviada.';await load()},scope)}async function revoke(id:number){await runWithTwoFactor(async()=>{await apiClient.post(`/admin/administrators/invitations/${id}/revoke`,undefined,{financialScope:scope});message.value='Invitación revocada.';await load()},scope)}async function toggle(item:any){await runWithTwoFactor(async()=>{await apiClient.patch(`/admin/administrators/${item.id}/status`,{active:item.status!=='Activa'},{financialScope:scope});await load()},scope)}onMounted(load);</script>
